from app.models import RecommendationResponse,RecommendationItem,BudgetAllocation
from app.services.platforms import search_url
def item(name,category,price,currency,platform,reason): return RecommendationItem(name=name,category=category,estimated_price=round(price,2),currency=currency,platform=platform,reason=reason,search_url=search_url(platform,name))
def home_fallback(d):
 b=d['budget'];c=d['currency'];s=d.get('style','Modern');alloc=[BudgetAllocation(category=x,amount=b*p,percentage=p*100) for x,p in [('Furniture',.42),('Lighting',.18),('Decor',.20),('Storage',.12),('Buffer',.08)]]
 rec=[item('Compact sofa','Furniture',b*.18,c,'Amazon',f'{s} seating sized for a controlled budget'),item('Dining table set','Furniture',b*.13,c,'IKEA','Flexible everyday dining option'),item('LED ceiling light','Lighting',b*.06,c,'Amazon','Efficient lighting with a broad style range'),item('Wall decor set','Decor',b*.08,c,'Flipkart','Adds visual interest without consuming the furniture budget'),item('Storage cabinet','Storage',b*.10,c,'IKEA','Practical storage that supports a tidy room')]
 return RecommendationResponse(planner='home',title='Home Interior Budget Plan',summary=f'A {s} home setup using a 42/18/20/12/8 budget split for furniture, lighting, decor, storage and buffer.',budget=b,currency=c,allocations=alloc,recommendations=rec,tips=['Measure rooms before buying furniture.','Keep the buffer for delivery, installation and unexpected accessories.'])
def party_fallback(d):
 b=d['budget'];c=d['currency'];g=d['guest_count'];alloc=[BudgetAllocation(category=x,amount=b*p,percentage=p*100) for x,p in [('Food & Catering',.45),('Venue',.20),('Decoration',.15),('Entertainment',.10),('Contingency',.10)]];pg=b*.45/g
 rec=[item('Catering package','Food & Catering',b*.45,c,'Zomato',f'Target about {pg:.0f} {c} per guest for food'),item('Party venue','Venue',b*.20,c,'OYO','Use the venue allocation as a ceiling'),item('Birthday decoration package','Decoration',b*.15,c,'Amazon','Keeps decoration spending separate from food'),item('Party entertainment','Entertainment',b*.10,c,'Amazon','Use a modest package and preserve contingency')]
 return RecommendationResponse(planner='party',title=f"{d['event_type']} Party Budget Plan",summary=f"Planning for {g} guests with food, venue, decoration, entertainment and contingency separated before shopping.",budget=b,currency=c,allocations=alloc,recommendations=rec,tips=['Confirm venue capacity and cancellation terms.','Compare catering cost per guest before committing.','Keep contingency untouched until final payments.'])
def jewelry_fallback(d,has_image=False):
 b=d['budget'];c=d['currency'];alloc=[BudgetAllocation(category=x,amount=b*p,percentage=p*100) for x,p in [('Primary piece',.55),('Secondary piece',.25),('Finishing piece',.12),('Buffer',.08)]];note=' The uploaded outfit image was received and can be used for visual matching when Gemini is enabled.' if has_image else ''
 rec=[item('Statement necklace','Primary piece',b*.55,c,'Amazon',f"Suitable for a {d['occasion']} with an {d['style']} preference."),item('Matching earrings','Secondary piece',b*.25,c,'Flipkart','Keeps the set coordinated without exhausting the budget.'),item('Minimal bracelet','Finishing piece',b*.12,c,'Amazon','A restrained finishing accessory.')]
 return RecommendationResponse(planner='jewelry',title=f"{d['occasion']} Jewelry Plan",summary=f"An {d['style']} jewelry allocation within budget.{note}",budget=b,currency=c,allocations=alloc,recommendations=rec,tips=['Match metal tone to the outfit accessories.','For heavily embellished outfits, keep jewelry simpler.','Verify material, size and return policy before purchase.'])
